package com.example.cvd;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import jakarta.annotation.PostConstruct;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.*;

@RestController
@RequestMapping("/api/vision")
public class VisionApi {
 final DataStore db; final AccessStore access; final KafkaTemplate<String,String> kafka; final TransactionTemplate tx;
 final boolean enabled; final Path catalog,images; final List<JsonNode> inputs=new ArrayList<>();
 public VisionApi(DataStore db,AccessStore access,KafkaTemplate<String,String> kafka,MetrologyApi metrology,@Value("${VISION_ENABLED:false}") boolean enabled,@Value("${VISION_CATALOG:vision/catalog}") String catalog,@Value("${VISION_IMAGES:.runtime/vision-images}") String images){this.db=db;this.access=access;this.kafka=kafka;this.enabled=enabled;this.catalog=Path.of(catalog);this.images=Path.of(images);tx=new TransactionTemplate(new DataSourceTransactionManager(db.pg.getDataSource()));}
 @PostConstruct void init()throws Exception {
  for(String s:new String(getClass().getResourceAsStream("/vision.sql").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).split(";"))if(!s.isBlank())db.pg.execute(s);
  if(enabled){for(JsonNode n:db.mapper.readTree(catalog.resolve("manifest.json").toFile())){verifyImage(catalog,n.path("hash").asText());inputs.add(n);}for(String kind:List.of("map","surface"))if(inputs.stream().noneMatch(n->n.path("kind").asText().equals(kind)))throw new IllegalStateException("missing vision modality");Files.createDirectories(images);db.pg.update("INSERT INTO vision_config(id) VALUES(1) ON CONFLICT DO NOTHING");}
 }
 static ResponseStatusException error(HttpStatus code){return new ResponseStatusException(code);}
 static String sha(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}
 static byte[] verifyImage(Path root,String hash)throws Exception {
  if(!hash.matches("[0-9a-f]{64}"))throw error(HttpStatus.BAD_REQUEST);
  Path p=root.resolve(hash+".png");if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.size(p)>2_000_000)throw error(HttpStatus.NOT_FOUND);
  byte[] bytes=Files.readAllBytes(p);if(!sha(bytes).equals(hash))throw error(HttpStatus.CONFLICT);if(bytes.length<24||bytes[0]!=(byte)137||bytes[1]!=80||bytes[2]!=78||bytes[3]!=71)throw error(HttpStatus.CONFLICT);var header=java.nio.ByteBuffer.wrap(bytes);int w=header.getInt(16),h=header.getInt(20);if(w<8||h<8||w>1024||h>1024)throw error(HttpStatus.CONFLICT);return bytes;
 }
 JsonNode input(String measurement,String kind){var a=inputs.stream().filter(n->n.path("kind").asText().equals(kind)).toList();return a.get(Math.floorMod((measurement+kind).hashCode(),a.size()));}
 void insert(String id,String measurement,int revision,String previous,String request,JsonNode source,JsonNode frozen){
  db.pg.update("INSERT INTO vision_runs(id,measurement_id,revision,previous_id,request_key,equipment_id,wafer_id,source) VALUES(?,?,?,?,?,?,?,?::jsonb)",id,measurement,revision,previous,request,source.path("equipmentId").asText(),source.path("waferId").asText(),source.toString());
  for(String kind:List.of("map","surface")){JsonNode in=frozen==null?input(measurement,kind):frozen.path(kind);db.pg.update("INSERT INTO vision_jobs(id,run_id,kind,input) VALUES(?,?,?,?::jsonb)",UUID.randomUUID().toString(),id,kind,in.toString());}
 }
 @Scheduled(fixedDelay=1500) void enqueue(){if(!enabled)return;tx.executeWithoutResult(t->{var rows=db.pg.queryForList("SELECT m.id,m.source::text FROM metrology_runs m JOIN vision_config c ON c.id=1 WHERE m.state='completed' AND m.completed_at>=c.enabled_at AND NOT EXISTS(SELECT 1 FROM vision_runs v WHERE v.measurement_id=m.id) ORDER BY m.completed_at LIMIT 20 FOR UPDATE OF m SKIP LOCKED");for(var row:rows)insert(UUID.randomUUID().toString(),(String)row.get("id"),1,null,null,db.parse((String)row.get("source")),null);});}
 @Scheduled(fixedDelay=2000) void dispatch(){if(!enabled)return;
  tx.executeWithoutResult(t->{db.pg.update("UPDATE vision_jobs SET state=CASE WHEN attempts>=3 THEN 'failed' ELSE 'queued' END,failure_reason='worker-timeout',lease=NULL,lease_until=NULL,last_sent=NULL WHERE state='running' AND lease_until<now()");
   for(var r:db.pg.queryForList("SELECT id FROM vision_jobs WHERE state='queued' AND (last_sent IS NULL OR last_sent<now()-interval '15 seconds') ORDER BY last_sent NULLS FIRST LIMIT 20 FOR UPDATE SKIP LOCKED"))try{kafka.send("vision.jobs.v1",(String)r.get("id"),db.mapper.createObjectNode().put("jobId",(String)r.get("id")).toString()).get(5,java.util.concurrent.TimeUnit.SECONDS);db.pg.update("UPDATE vision_jobs SET last_sent=now() WHERE id=?",r.get("id"));}catch(Exception e){throw new IllegalStateException("vision dispatch unavailable",e);}
   aggregate();});
 }
 @PostMapping("/worker/jobs/{id}/claim") public JsonNode claim(@PathVariable String id){if(!enabled)throw error(HttpStatus.CONFLICT);return tx.execute(t->{var rows=db.pg.queryForList("SELECT input::text,kind FROM vision_jobs WHERE id=? AND state='queued' FOR UPDATE",id);if(rows.isEmpty())throw error(HttpStatus.CONFLICT);String lease=UUID.randomUUID().toString();db.pg.update("UPDATE vision_jobs SET state='running',attempts=attempts+1,lease=?,lease_until=now()+interval '30 seconds' WHERE id=?",lease,id);var n=db.mapper.createObjectNode().put("jobId",id).put("lease",lease).put("kind",(String)rows.getFirst().get("kind"));n.set("input",db.parse((String)rows.getFirst().get("input")));return n;});}
 @GetMapping(value="/worker/jobs/{id}/input",produces="image/png") public byte[] workerInput(@PathVariable String id,@RequestHeader("X-Vision-Lease") String lease)throws Exception{var a=db.pg.queryForList("SELECT input->>'hash' FROM vision_jobs WHERE id=? AND lease=? AND state='running' AND lease_until>now()",String.class,id,lease);if(a.isEmpty())throw error(HttpStatus.CONFLICT);return verifyImage(catalog,a.getFirst());}
 @KafkaListener(topics="vision.results.v1",groupId="vision-results-v1") synchronized void result(String raw){JsonNode e=db.parse(raw);String id=e.path("jobId").asText(),lease=e.path("lease").asText();tx.executeWithoutResult(t->{var rows=db.pg.queryForList("SELECT input::text,kind FROM vision_jobs WHERE id=? AND lease=? AND state='running' AND lease_until>now() FOR UPDATE",id,lease);if(rows.isEmpty())return;JsonNode in=db.parse((String)rows.getFirst().get("input")),r=e.path("result");boolean valid=e.path("state").asText().equals("completed")&&validResult(r,in);if(valid)try{verifyImage(images,r.path("overlayHash").asText());}catch(Exception ex){valid=false;}
   db.pg.update("UPDATE vision_jobs SET state=?,result=?::jsonb,failure_reason=?,lease=NULL,lease_until=NULL WHERE id=?",valid?"completed":"failed",valid?r.toString():null,valid?null:"analysis-failed",id);aggregate();});}
 static boolean validResult(JsonNode r,JsonNode in){
  if(!r.path("inputHash").asText().equals(in.path("hash").asText())||!r.path("kind").asText().equals(in.path("kind").asText())||r.path("width").asInt()!=in.path("width").asInt()||r.path("height").asInt()!=in.path("height").asInt()||!r.path("algorithmVersion").asText().equals("opencv-rules-v1")||r.path("opencvVersion").asText().isBlank()||!r.path("parameters").isObject()||!Set.of("pass","review","uncertain").contains(r.path("quality").asText())||!r.path("candidates").isArray()||r.path("candidates").isEmpty()||!r.path("defects").isArray()||r.path("defects").size()>1000||!r.path("overlayHash").asText().matches("[0-9a-f]{64}"))return false;
  Set<String> allowed=r.path("kind").asText().equals("map")?Set.of("center","donut","edge-ring","edge-loc","loc","random","scratch","near-full","none","uncertain"):Set.of("particle","scratch","spot","none","uncertain");Set<String> candidates=new HashSet<>();for(JsonNode c:r.path("candidates"))if(!allowed.contains(c.asText())||!candidates.add(c.asText()))return false;String expected=candidates.contains("uncertain")?"uncertain":candidates.equals(Set.of("none"))?"pass":"review";if(!expected.equals(r.path("quality").asText())||(candidates.contains("none")&&(candidates.size()!=1||!r.path("defects").isEmpty())))return false;
  for(JsonNode d:r.path("defects")){for(String k:List.of("x","y","width","height","areaPx","sizePx"))if(!d.path(k).isNumber()||!Double.isFinite(d.path(k).asDouble())||d.path(k).asDouble()<0)return false;if(d.path("width").asInt()<1||d.path("height").asInt()<1||d.path("x").asDouble()+d.path("width").asDouble()>r.path("width").asInt()||d.path("y").asDouble()+d.path("height").asDouble()>r.path("height").asInt())return false;if(d.has("sizeUm")&&(in.path("calibration").isNull()||!in.path("calibration").isNumber()||!d.path("sizeUm").isNumber()||!Double.isFinite(d.path("sizeUm").asDouble())))return false;}
  return true;
 }
 void aggregate(){db.pg.update("UPDATE vision_runs r SET completed_at=now(),alarm=EXISTS(SELECT 1 FROM vision_jobs j WHERE j.run_id=r.id AND j.result->>'quality'='review') WHERE completed_at IS NULL AND (SELECT count(*) FROM vision_jobs j WHERE j.run_id=r.id)=2 AND NOT EXISTS(SELECT 1 FROM vision_jobs j WHERE j.run_id=r.id AND state IN ('queued','running'))");}
 @GetMapping("/runs") public List<JsonNode> list(@RequestParam String measurementId){return db.pg.queryForList("SELECT to_jsonb(v)::text FROM vision_runs v WHERE measurement_id=? ORDER BY revision DESC",String.class,measurementId).stream().map(db::parse).toList();}
 @GetMapping("/runs/{id}") public JsonNode detail(@PathVariable String id){var rows=db.pg.queryForList("SELECT (to_jsonb(v)||jsonb_build_object('jobs',(SELECT jsonb_agg(to_jsonb(j)-'lease'-'lease_until') FROM vision_jobs j WHERE j.run_id=v.id)))::text FROM vision_runs v WHERE id=?",String.class,id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND);return db.parse(rows.getFirst());}
 @GetMapping(value="/jobs/{id}/image/{type}",produces="image/png") public byte[] image(@PathVariable String id,@PathVariable String type)throws Exception{if(!Set.of("original","overlay").contains(type))throw error(HttpStatus.BAD_REQUEST);var rows=db.pg.queryForList("SELECT j.input::text,j.result::text,r.expired FROM vision_jobs j JOIN vision_runs r ON r.id=j.run_id WHERE j.id=?",id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND);var row=rows.getFirst();if(Boolean.TRUE.equals(row.get("expired")))throw error(HttpStatus.GONE);return type.equals("original")?verifyImage(catalog,db.parse((String)row.get("input")).path("hash").asText()):verifyImage(images,db.parse((String)row.get("result")).path("overlayHash").asText());}
 @PostMapping("/runs/{id}/reanalyze") public Map<String,String> reanalyze(@PathVariable String id,@RequestBody Map<String,String> body){MetrologyApi.engineer();if(!enabled)throw error(HttpStatus.CONFLICT);String request=body.get("requestId");try{UUID.fromString(request);}catch(Exception e){throw error(HttpStatus.BAD_REQUEST);}return tx.execute(t->{db.pg.execute("SELECT pg_advisory_xact_lock(81344024)");var row=detail(id);String measurement=row.path("measurement_id").asText();db.pg.queryForList("SELECT id FROM metrology_runs WHERE id=? FOR UPDATE",measurement);String key=AccessSessions.actor().id()+"/"+id+"/"+request;var old=db.pg.queryForList("SELECT id FROM vision_runs WHERE request_key=?",String.class,key);if(!old.isEmpty())return Map.of("id",old.getFirst());if(row.path("expired").asBoolean()||row.path("completed_at").isNull())throw error(HttpStatus.CONFLICT);var frozen=db.mapper.createObjectNode();for(JsonNode j:row.path("jobs"))frozen.set(j.path("kind").asText(),j.path("input"));int rev=db.pg.queryForObject("SELECT max(revision)+1 FROM vision_runs WHERE measurement_id=?",Integer.class,measurement);String next=UUID.randomUUID().toString();insert(next,measurement,rev,id,key,row.path("source"),frozen);access.audit(AccessSessions.actor(),"vision-reanalyze",next,id,measurement);return Map.of("id",next);});}
 @GetMapping("/alarms") public List<JsonNode> alarms(@RequestParam String equipmentId){Equipment.require(equipmentId);return db.pg.queryForList("SELECT to_jsonb(v)::text FROM vision_runs v WHERE equipment_id=? AND alarm AND NOT acknowledged ORDER BY created_at DESC LIMIT 100",String.class,equipmentId).stream().map(db::parse).toList();}
 @PostMapping("/runs/{id}/acknowledge") public Map<String,Boolean> acknowledge(@PathVariable String id){MetrologyApi.engineer();if(db.pg.update("UPDATE vision_runs SET acknowledged=true WHERE id=? AND alarm",id)!=1)throw error(HttpStatus.NOT_FOUND);access.audit(AccessSessions.actor(),"vision-alarm-ack",id,"","");return Map.of("ok",true);}
 @Scheduled(fixedDelay=3600000) synchronized void cleanup(){if(!enabled)return;tx.executeWithoutResult(t->{db.pg.execute("SELECT pg_advisory_xact_lock(81344024)");var expired=db.pg.queryForList("UPDATE vision_runs r SET expired=true WHERE NOT expired AND completed_at<now()-interval '30 days' AND (NOT alarm OR acknowledged) AND NOT EXISTS(SELECT 1 FROM vision_runs active WHERE active.measurement_id=r.measurement_id AND active.completed_at IS NULL) RETURNING id",String.class);for(String id:expired)db.pg.update("UPDATE vision_jobs SET result=NULL WHERE run_id=?",id);});
  try(var files=Files.list(images)){var used=new HashSet<>(db.pg.queryForList("SELECT result->>'overlayHash' FROM vision_jobs WHERE result IS NOT NULL",String.class));files.filter(p->p.getFileName().toString().matches("[0-9a-f]{64}\\.png")).forEach(p->{try{String h=p.getFileName().toString().substring(0,64);if(!used.contains(h)&&Files.getLastModifiedTime(p).toInstant().isBefore(Instant.now().minusSeconds(86400)))Files.deleteIfExists(p);}catch(Exception e){throw new IllegalStateException(e);}});}catch(java.io.IOException e){throw new IllegalStateException(e);}
 }
}
